.aegis-busy-overlay{position:absolute;inset:0;z-index:80;display:grid;place-items:center;background:rgba(0,5,12,.84);backdrop-filter:blur(2px);opacity:0;pointer-events:none;transition:opacity .16s ease}.aegis-busy-overlay.visible{opacity:1;pointer-events:auto}.aegis-sensor{position:relative;width:min(420px,72vw);aspect-ratio:1;display:grid;place-items:center}.aegis-sensor-ring{position:absolute;border-radius:50%;border:1px solid rgba(102,204,255,.35);box-shadow:inset 0 0 20px rgba(85,136,238,.08)}.aegis-sensor-ring.r1{width:82%;height:82%;border-top:3px solid #5588ee;border-right:2px solid rgba(255,204,102,.78);animation:sensorSpin 5.5s linear infinite}.aegis-sensor-ring.r2{width:64%;height:64%;border-left:3px solid #7799dd;border-bottom:2px solid #66ccff;animation:sensorSpinReverse 4.2s linear infinite}.aegis-sensor-ring.r3{width:46%;height:46%;border-top:2px solid #99ccff;border-left:2px solid rgba(255,204,102,.85);animation:sensorSpin 3.4s linear infinite}.aegis-sensor-ticks{position:absolute;width:92%;height:92%;border-radius:50%;background:repeating-conic-gradient(from 0deg,rgba(102,204,255,.42) 0 1deg,transparent 1deg 10deg);mask:radial-gradient(circle,transparent 0 42%,#000 43% 45%,transparent 46%)}.aegis-sensor-sweep{position:absolute;width:78%;height:78%;border-radius:50%;background:conic-gradient(from 0deg,transparent 0 318deg,rgba(102,204,255,.04) 326deg,rgba(102,204,255,.55) 349deg,rgba(255,204,102,.78) 358deg,transparent 360deg);filter:drop-shadow(0 0 9px rgba(102,204,255,.7));animation:sensorSpin 1.75s linear infinite}.aegis-sensor-pulse{position:absolute;width:28%;height:28%;border:1px solid rgba(102,204,255,.55);border-radius:50%;animation:sensorPulse 1.45s ease-out infinite}.aegis-sensor-core{position:relative;z-index:3;width:72px;height:78px;border:2px solid #66ccff;border-radius:8px;background:linear-gradient(180deg,#0b2638,#06121d);box-shadow:0 0 22px rgba(102,204,255,.75),0 0 0 5px rgba(85,136,238,.10);display:grid;align-content:center;gap:7px;padding:11px}.aegis-sensor-core i{display:block;height:6px;border-radius:2px;background:#99ccff;box-shadow:0 0 6px rgba(153,204,255,.75)}.aegis-sensor-core i:nth-child(2){background:#88eeff}.aegis-sensor-core i:nth-child(3){background:#7799dd}.aegis-sensor-copy{position:absolute;left:50%;bottom:-58px;transform:translateX(-50%);width:420px;text-align:center;text-transform:uppercase;font:900 13px/1.3 Arial,sans-serif;letter-spacing:.12em;color:#66ccff}.aegis-sensor-copy b{display:block;color:#f3f3fc;font-size:18px;margin-bottom:5px}.aegis-sensor-copy span{color:#ffcc66}.aegis-sensor-dot{position:absolute;width:9px;height:9px;border-radius:50%;background:#ffcc66;box-shadow:0 0 10px #ffcc66}.aegis-sensor-dot.d1{top:8%;left:47%}.aegis-sensor-dot.d2{right:10%;top:52%;background:#66ccff;box-shadow:0 0 10px #66ccff}.aegis-sensor-dot.d3{left:14%;bottom:20%;background:#7799dd;box-shadow:0 0 10px #7799dd}@keyframes sensorSpin{to{transform:rotate(360deg)}}@keyframes sensorSpinReverse{to{transform:rotate(-360deg)}}@keyframes sensorPulse{0%{transform:scale(.65);opacity:.85}100%{transform:scale(2.5);opacity:0}}@media(prefers-reduced-motion:reduce){.aegis-sensor-ring,.aegis-sensor-sweep,.aegis-sensor-pulse{animation:none}}}</style>
