    private const string ApplicationsScript = """
async function load(){
 try{
  const [registered,telemetry]=await Promise.all([fetch('/api/operations/registered-applications',{cache:'no-store'}).then(r=>r.json()),fetch('/api/operations/applications',{cache:'no-store'}).then(r=>r.json())]);
  const apps=registered.applications||[], history=registered.history||[], raw=telemetry||[], byKey=new Map(raw.map(x=>[(x.applicationId+'|'+x.instanceId).toLowerCase(),x]));
  const uniqueApps=new Set(apps.map(x=>x.applicationId)), envs=new Set(apps.map(x=>x.environment).filter(x=>x&&x!=='—'));
  const configurationReady=x=>!x.configurationStatus||['published','configured','healthy','ready'].includes(String(x.configurationStatus).toLowerCase());
  const healthy=apps.filter(x=>String(x.state).toLowerCase()==='healthy'&&!x.stale&&configurationReady(x)).length, attention=apps.length-healthy;
  appTotal.textContent=uniqueApps.size;instanceTotal.textContent=apps.length;healthyTotal.textContent=healthy;attentionTotal.textContent=attention;environmentTotal.textContent=envs.size;
  authority.textContent=registered.authorityAvailable?'Configuration registration authority online · operational state merged by instance':'Registration authority unavailable'+(registered.authorityError?' · '+registered.authorityError:'');
  appsBody.innerHTML=apps.length?apps.map(a=>{const op=byKey.get((a.applicationId+'|'+a.instanceId).toLowerCase())||{};const deps=op.dependencies||[];return '<tr><td><b>'+esc(a.displayName||a.applicationId)+'</b><small>'+esc(a.applicationId)+(deps.length?' · '+deps.length+' dependencies':'')+'</small></td><td>'+esc(a.instanceId)+'</td><td>'+esc(a.environment)+'</td><td>'+esc(a.version||'—')+'<small>'+esc(a.build||'No build published')+'</small></td><td><span class="state '+esc(a.registrationFlowTone||'')+'">'+esc(a.registrationFlowLabel||a.registrationStatus||'Unknown')+'</span><small>'+esc(a.registrationHealth||'')+'</small></td><td><span class="state '+esc(a.state)+'">'+esc(a.stale?'Offline':a.state)+'</span><small>'+esc(a.reason||'')+'</small></td><td>'+esc(a.configurationStatus||'—')+'</td><td>'+fmt(a.observedAtUtc||a.registrationObservedAtUtc)+'</td></tr>'}).join(''):'<tr><td colspan="8">No applications registered.</td></tr>';
  const issues=apps.filter(a=>String(a.state).toLowerCase()!=='healthy'||a.stale||String(a.registrationHealth).toLowerCase()==='attention'||!configurationReady(a));
  attentionList.innerHTML=issues.length?issues.map(a=>'<div class="activity-row"><b>'+esc(a.applicationId)+'</b><span class="state '+esc(a.state)+'">'+esc(!configurationReady(a)?(a.configurationStatus||'Attention'):(a.stale?'Offline':a.state))+'</span><span>'+esc(a.reason||a.registrationHealth||'Attention required')+'</span></div>').join(''):'<div class="muted">No application conditions require attention.</div>';
  const depRows=raw.filter(x=>(x.dependencies||[]).length).map(x=>'<div class="activity-row"><b>'+esc(x.applicationId)+'</b><span>'+esc(x.instanceId)+'</span><span class="chips">'+x.dependencies.map(d=>'<span class="chip">'+esc(d)+'</span>').join('')+'</span></div>');
  dependencyList.innerHTML=depRows.length?depRows.join(''):'<div class="muted">No dependency telemetry has been published.</div>';
  window.__historyCount=history.length;
  historyBody.innerHTML=history.length?history.map(a=>'<tr><td><b>'+esc(a.displayName||a.applicationId)+'</b><small>'+esc(a.applicationId)+'</small></td><td>'+esc(a.instanceId||'—')+'</td><td>'+esc(a.environment||'—')+'</td><td>'+esc(a.version||'—')+'</td><td><span class="state">'+esc(a.registrationStatus||'Historical')+'</span><small>'+esc(a.registrationHealth||'')+'</small></td><td>'+fmt(a.lastSeenAtUtc)+'</td><td><code>'+esc(a.registrationId||'—')+'</code></td></tr>').join(''):'<tr><td colspan="7">No historical instances have been retained.</td></tr>';
  historyToggle.textContent=instanceHistory.hidden?(history.length?'Show History ('+history.length+')':'Show History'):'Hide History';
  const recentApps=[...apps].filter(a=>a.observedAtUtc||a.registrationObservedAtUtc).sort((a,b)=>new Date(b.observedAtUtc||b.registrationObservedAtUtc)-new Date(a.observedAtUtc||a.registrationObservedAtUtc)).slice(0,5);
  lastScan.textContent='Last Scan: '+fmt(new Date());
 }catch(e){appsBody.innerHTML='<tr><td colspan="8">Application inventory unavailable · '+esc(e.message)+'</td></tr>';lastScan.textContent='Last Scan: UNAVAILABLE'}
}
historyToggle.onclick=()=>{instanceHistory.hidden=!instanceHistory.hidden;historyToggle.textContent=instanceHistory.hidden?(window.__historyCount?'Show History ('+window.__historyCount+')':'Show History'):'Hide History'};load();refreshRecentLogs();setInterval(load,15000);setInterval(refreshRecentLogs,5000);
""";

    private const string DeploymentsBody = """
<section class="metrics"><div class="metric"><b id="deployApps">—</b><small>Observed Apps</small></div><div class="metric"><b id="builds">—</b><small>Builds Published</small></div><div class="metric"><b id="ready">—</b><small>Ready / Healthy</small></div><div class="metric"><b id="blocked">—</b><small>Attention</small></div><div class="metric"><b id="syncCount">—</b><small>Deployment Targets</small></div></section>
<section class="panel"><h2>Release / Deployment Inventory</h2><div class="muted">Observed deployment readiness based on application version, build, registration, configuration and runtime telemetry.</div><div class="table-scroll"><table><thead><tr><th>Application</th><th>Instance</th><th>Environment</th><th>Version</th><th>Build</th><th>Runtime State</th><th>Configuration</th><th>Readiness</th><th>Observed</th></tr></thead><tbody id="deployBody"><tr><td colspan="9">Loading…</td></tr></tbody></table></div></section>
<section class="two"><section class="panel"><h2>Deployment Targets</h2><div class="muted">Endpoints or synchronization targets explicitly published by applications for deployment-related operations.</div><div id="syncList">Loading…</div></section><section class="panel"><h2>Recent Deployment Activity</h2><div id="historyList">Loading…</div></section></section>
<section class="panel"><h2>Deployment Readiness</h2><div class="muted">This page currently observes release and deployment state. Execution controls will appear only after an application publishes an explicit deployment contract.</div></section>
""";

    private const string DeploymentsScript = """
async function safeJson(url,fallback){try{const r=await fetch(url,{cache:'no-store'});return r.ok?await r.json():fallback}catch{return fallback}}
async function load(){
 const [registered,sync,history]=await Promise.all([safeJson('/api/operations/registered-applications',{applications:[]}),safeJson('/api/operations/synchronization',[]),safeJson('/api/operations/history',[])]);
 const rows=Array.isArray(registered)?registered:(registered.applications||[]),
       registrationFresh=a=>String(a.registrationStatus||'').toLowerCase()==='registered'&&!a.stale&&!!a.registrationObservedAtUtc,
       effectiveState=a=>registrationFresh(a)&&String(a.state||'').toLowerCase()==='offline'?'Healthy':String(a.state||'Unknown'),
       isReady=a=>String(effectiveState(a)).toLowerCase()==='healthy'&&!a.stale&&(!a.configurationStatus||['configured','healthy','ready','published'].includes(String(a.configurationStatus).toLowerCase()));
 deployApps.textContent=new Set(rows.map(x=>x.applicationId)).size;builds.textContent=rows.filter(x=>x.build).length;ready.textContent=rows.filter(isReady).length;blocked.textContent=rows.filter(x=>!isReady(x)).length;syncCount.textContent=(sync||[]).length;
 const statusClass=v=>{const s=String(v||'Unknown').toLowerCase();if(['healthy','running','ready','configured','published','succeeded','success','completed','online'].includes(s))return 'Healthy';if(['unhealthy','failed','critical','error','blocked'].includes(s))return 'Failed';return 'Warning'};
 deployBody.innerHTML=rows.length?rows.map(a=>{const s=effectiveState(a);return '<tr><td><b>'+esc(a.displayName||a.applicationId)+'</b><small>'+esc(a.applicationId)+'</small></td><td>'+esc(a.instanceId)+'</td><td>'+esc(a.environment)+'</td><td>'+esc(a.version||'—')+'</td><td>'+esc(a.build||'—')+'</td><td><span class="state '+statusClass(s)+'">'+esc(s)+'</span><small>'+esc(a.reason||'')+'</small></td><td><span class="state '+statusClass(a.configurationStatus)+'">'+esc(a.configurationStatus||'—')+'</span></td><td><span class="state '+(isReady(a)?'Ready':'Failed')+'">'+(isReady(a)?'READY':'ATTENTION')+'</span></td><td>'+fmt(a.observedAtUtc||a.registrationObservedAtUtc)+'</td></tr>'}).join(''):'<tr><td colspan="9">No deployment telemetry has been observed.</td></tr>';
 syncList.innerHTML=(sync||[]).length?(sync||[]).slice(0,12).map(x=>'<div class="activity-row"><b>'+esc(x.applicationId||'Application')+'</b><span>'+esc(x.name||x.endpointId||x.direction||'Sync')+'</span><span>'+esc(x.state||x.status||x.detail||'Observed')+'</span></div>').join(''):'<div class="muted">No deployment targets have been published by applications.</div>';
 historyList.innerHTML=(history||[]).length?(history||[]).slice(0,12).map(x=>'<div class="activity-row"><b>'+fmt(x.at||x.atUtc||x.observedAtUtc||x.timestampUtc)+'</b><span>'+esc(x.application||x.type||'Operations')+'</span><span>'+esc(x.text||x.message||'Operational event')+'</span></div>').join(''):'<div class="muted">No recent deployment or release activity has been observed.</div>';
 liveLog.innerHTML=(history||[]).slice(0,5).map(x=>'<div class="row"><span class="t">'+fmt(x.at||x.atUtc||x.observedAtUtc||x.timestampUtc)+'</span> <span class="inf">INF</span> <span class="src">['+esc(x.application||x.type||'Operations')+']</span> '+esc(x.text||'Operational event')+'</div>').join('')||'<div class="row"><span class="t">--</span> <span class="inf">INF</span> <span class="src">[Deployments]</span> No recent deployment activity</div>';
 lastScan.textContent='Last Scan: '+fmt(new Date());
}
load();refreshRecentLogs();setInterval(load,15000);setInterval(refreshRecentLogs,5000);
""";
}

